-- ============================================================
-- Migration 169 -- Crash courses: weeks, classes and items found by folder, not by id
--
-- Live's IELTS Academic Crash Course still showed Week 1 as "Orientation, Diagnostic & Listening Start" with one item
-- ("Orientation & Diagnostic Assessment"): the state migration 134 copied from the 2-Month Masterclass. Every later
-- crash-course change (151, 153, 157, 158, 160, 161) found the course by its LOCAL id (23; 10, 12, 18 for the others),
-- so on live, where the ids differ, they changed nothing and said nothing.
--
-- This sets all four crash courses to exactly the shape local has (generated from local, 2026-10-24), found by
-- courses.folder_name and by week/class position: week titles and plan levels; class titles, first page, icon, length
-- and plan level (class ids kept, so progress stays); every class's items replaced (nothing refers to an item by id).
-- Lesson text and video links are not touched. Overwrites any hand edits to these titles made in SLS Admin.
-- Run AFTER 168 (the Foundational English Assessment items point at its test, FEA50_A).
-- One transaction. Re-runnable. MySQL 5.7-safe. The SELECT at the end lists weeks / classes / items per course.
-- ============================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- ---------------- IELTS_Gen_1Mo ----------------
UPDATE modules m JOIN courses c ON c.id = m.course_id AND c.folder_name = 'IELTS_Gen_1Mo' SET m.module_title = 'Week 1 — Introduction & First Steps', m.min_tier = 'intermediate' WHERE m.module_order = 1;
