-- Expected: IELTS_Gen_1Mo: 4 weeks, 8 classes, 27 items; CELPIP_Gen_1Mo: 4 weeks, 8 classes, 21 items; PTE_Gen_1Mo: 4 weeks, 8 classes, 12 items; IELTS_Aca_1Mo: 4 weeks, 8 classes, 16 items.
SELECT c.id, c.folder_name, COUNT(DISTINCT m.id) AS weeks, COUNT(DISTINCT l.id) AS classes, COUNT(p.id) AS items
  FROM courses c JOIN modules m ON m.course_id = c.id JOIN lessons l ON l.module_id = m.id LEFT JOIN lesson_parts p ON p.lesson_id = l.id
 WHERE c.folder_name IN ('IELTS_Gen_1Mo', 'CELPIP_Gen_1Mo', 'PTE_Gen_1Mo', 'IELTS_Aca_1Mo') GROUP BY c.id, c.folder_name;
